// TH16 v1.00a Extra boss BossCard3「秘儀「弾幕の玉繭」」 (st07bs.ecl.txt:1371-1422)
// Source boundary handling: previous-card tail/清弹/即时子敌/表现/掉落 are omitted per policy;
// the card's own movement, waits, spawns and shooting are kept.

const TIME_LIMIT: int = 4324;   // OPENING_BUFFER 120 + source spell window 4200 + 4 startup margin
const OPENING_BUFFER: int = 120;
const BOSS_HP: int = 3500;      // Boss entry lifeSet(3500) for SPELL_ID 111

// TH16 etSprite types (approved 0-43 aliases): 8=RICE, 6=RING_BALL
const TH16_RICE: int = 480;        // etSprite(0, 8, 10)
const TH16_RING_BALL: int = 448;   // etSprite(1, 6, 13)
const AT_COLOR: int = 10;
const AT2_COLOR: int = 13;

// BossCard3_at: etEx effect 0x10 ANGLE_ACCEL, a=240, r=+0.01 speed/frame,
// s=+0.023561945 rad/frame (~246 BAM/frame). Effect ends after 240 ticks.
xformdef AT_SPIN_CW {
    set_ang_vel(246bam);
    set_accel(0.01fx);
    wait(240);
    set_ang_vel(0bam);
    set_accel(0fx);
}
// Same record with s=-0.023561945 for the mirrored bullet.
xformdef AT_SPIN_CCW {
    set_ang_vel(-246bam);
    set_accel(0.01fx);
    wait(240);
    set_ang_vel(0bam);
    set_accel(0fx);
}
// BossCard3_at2: etExSet2 effect 0x10 STEP, a=1, b=1, c=0, d=0,
// r=%RANDF2*0.17453292 (signed +-10deg), s=-1.0 target speed.
// One segment: draw the birth speed for its single tick, then angle+=r and speed=s.
// A negative source speed reverses the scalar direction, hence set_speed(-1fx).
xformdef AT2_STEP(offset: angle, target_speed: fx) {
    wait(1);
    turn(offset);
    set_speed(target_speed);
}

// BossCard3_at: every wait(2) two bullets from the 160px birth ring, angles diverge +-2deg.
// etDist(160) with ANIM a=1 retreat 4*v (v=0.01) gives a net 159.96px birth distance.
// Source BossCard3_at itself runs 10000 iterations, cut off by the 4200-frame spell
// interrupt (setInterrupt -> Boss4). The boss task age is the source spell timer, so the
// emitters stop at 4200; the main task then returns and the enemy retreats silently,
// taking the at2 child task with it.
sub at_loop() {
    var a: angle = -90deg;   // %A = -1.570796
    var b: angle = -90deg;   // %B = -1.570796
    while $self_age < 4200 {
        _ = fire(TH16_RICE, AT_COLOR,
                 $self_x + 159.96fx * cos(a), $self_y + 159.96fx * sin(a),
                 0.01fx, a, AT_SPIN_CW, none);
        _ = fire(TH16_RICE, AT_COLOR,
                 $self_x + 159.96fx * cos(b), $self_y + 159.96fx * sin(b),
                 0.01fx, b, AT_SPIN_CCW, none);
        a = a + 2deg;   // %A += 0.034907 rad
        b = b - 2deg;   // %B -= 0.034907 rad
        wait(2);
    }
}

// BossCard3_at2 (async): wait(300), then one bullet every 30 frames.
// Source floatTime(0,%F0,0,3600,30,2) has frames=0, so it only writes start=30;
// $B = _S(%F0) is therefore 30 each iteration.
async sub at2_emitter() {
    wait(300);
    var a: angle = -90deg;   // %A = -1.570796
    loop {
        var off: angle = ((rand(65536) - 32768) * 1820 / 32768) as angle;  // %RANDF2*0.17453292
        _ = fire(TH16_RING_BALL, AT2_COLOR,
                 $self_x + 159.96fx * cos(a), $self_y + 159.96fx * sin(a),
                 0.01fx, a, AT2_STEP(off, -1fx), none);
        a = a + 40503bam;   // %A += 3.883222 rad
        wait(30);
    }
}

// Boss entry state at the card (Boss context: hurtbox 40/40, hitbox 48/48, movePos(0,128)).
// Card motion: movePosTime(60, mode4, 0, 224); +90 time label; then at2 async + BossCard3_at.
async sub boss() {
    set_invuln(65535);
    set_hurtbox(20fx);   // setHurtbox(40,40)
    set_hitbox(24fx);    // setHitbox(48,48)
    move_to(60, 0fx, 224fx, EASE_QUAD_OUT);
    wait(90);
    // moveLimit(0,224,240,64) at the +90 label never clips: the boss stays still at (0,224).
    spawn at2_emitter();
    at_loop();           // source BossCard3_at call; returns at the 4200-frame spell timeout
}

async sub pattern() {
    wait(OPENING_BUFFER);
    _ = spawn_enemy(0fx, 128fx, BOSS_HP, 0, 0, 0, boss);
}

async sub control() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    phase_begin(0, pattern, TIME_LIMIT, 0);
    wait_spell();
    loop { wait(1); }
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, control);
    loop { wait(600); }
}
